SELECT EXISTS (
    SELECT 1
    FROM merchants m
    WHERE m.id = #{merchantId}
)

SELECT EXISTS (
    SELECT 1
    FROM bookmarks b
    WHERE b.users_id = #{userId}
      AND b.merchants_id = #{merchantId}
      AND b.is_deleted IS NULL
)

mapper.insert:
INSERT INTO bookmarks (
    users_id, merchants_id, created_at, updated_at
) VALUES (
    #{userId}, #{merchantId}, NOW(), NOW()
)

mapper.select:
SELECT b.id AS bookmark_id, b.merchants_id, b.created_at, m.category, m.name, m.address, m.thumbnail_url, m.price, CASE WHEN EXISTS ( SELECT 1 FROM reviews r WHERE r.merchant_id = m.id AND r.status = 'ACTIVE' ) THEN COALESCE(m.rating, 0.0) ELSE 0.0 END AS rating, (SELECT COUNT(*) FROM reviews r WHERE r.merchant_id = m.id AND r.status = 'ACTIVE') AS review_count FROM bookmarks b JOIN merchants m ON b.merchants_id = m.id WHERE b.users_id = #{userId} AND b.is_deleted IS NULL
AND m.category = #{category}
AND b.id < #{cursor}
ORDER BY b.created_at DESC, b.id DESC LIMIT #{size}
